    /// A mask from any rule over what is seen: `view.mask(|p| ...)`.
    pub fn mask(&self, g: impl Fn(&Point) -> f32 + Sync) -> Mask {
        let f = self.f;
        let inv = 1.0 / f.scale;
        let data = (0..f.w * f.h).into_par_iter().map(|i| g(&self.at(((i % f.w) as f32 + 0.5) * inv, ((i / f.w) as f32 + 0.5) * inv))).collect();
