s=s.replace('''/// The cart track: its centerline on the ground (X, Z m).
const TRACK: [(f32, f32); 7] = [(10.5, 9.0), (8.2, 15.0), (5.0, 23.0), (1.2, 33.0), (-3.0, 44.0), (-6.8, 54.0), (-9.6, 66.0)];
const TRACK_W: f32 = 2.7;''','''/// The cart track: its middle (X m) at depth z, from the right edge over
