    /// later crack, splitting a smaller island, opens less (by the stress it
    /// released: in a passage that only began cracking late, as with
    /// `patchy`, the first cracks still open like primaries). Cracks
    /// also swell and pinch along their length and close to nothing for
    /// stretches (notes/cracks.md, Round 7).
    pub hierarchy: f32,
    /// How patchily the network developed, 0 (evenly) .. 1: the ground was
    /// primed unevenly and the glue size and paint differ from place to
    /// place, so over some centimeters one passage split into small islands
    /// while another kept only its first few long cracks.
    pub patchy: f32,
    /// A dominant direction, 0 (none) .. 1: the canvas was stretched
    /// tighter along its length (keying out, the weave's crimp), so the
    /// first cracks run across it; the direction drifts over the canvas.
    pub grain: f32,
    /// What fills the cracks, 0 (the old even soot) .. 1: gray-brown grime
    /// that differs crack to crack (wide ones hold more; a cleaning took it
    /// out of some; old varnish stayed amber in others) over walls that
    /// show the pale ground, so in darks a crack reads as a faint light line.
    pub grime: f32,
    pub seed: u64,
}
/// Island size per µm of layer (ground + paint): channel cracks in a film
/// on a compliant support saturate at a spacing of some ten to twenty film
/// thicknesses. 14 puts a 240 µm Friedrich ground at ~3.6 mm, inside the
/// 2–6 mm the research notes give (assumption, calibrated to that range).
pub const ISLAND_PER_UM: f32 = 14.0e-3;
/// Paint film over the ground assumed when sizing islands, µm.
const PAINT_UM: f32 = 20.0;
/// A crack opens by the film's strain times the island size: shrinkage and
/// the canvas's slack, ~1% after two centuries (assumption; a 3.5 mm island
/// opens 32 µm, under the 70 µm the OCT study measured on a wide crack).
pub const STRAIN: f32 = 0.009;
impl Cracks {
    /// A quietly aged canvas, fitted to the canvas it cracks: islands and
    /// weave coupling from its ground, openings from the island size (about
    /// 30 µm on a Friedrich ground), 20 µm deep after varnish, a little
    /// grime and cupping, uneven aging and a few patches of milky varnish.
    pub fn aged(seed: u64) -> Self {
        Cracks {
            island_mm: None,
            ground_um: None,
            width_um: None,
            depth_um: 20.0,
            cupping_um: 15.0,
            dirt: 0.4,
            corners: true,
            vary: 1.0,
            veil: 0.5,
            hierarchy: 1.0,
            patchy: 1.0,
            grain: 0.15,
            grime: 1.0,
            seed,
        }
    }
    /// The Round 6 recipe: one even network (every crack alike, no patchy
    /// development, no direction, the old soot in the cracks), fitted to
    /// the canvas like `aged`.
    pub fn even(seed: u64) -> Self {
        Cracks { hierarchy: 0.0, patchy: 0.0, grain: 0.0, grime: 0.0, ..Cracks::aged(seed) }
    }
    /// The recipe fitted to a canvas primed with `ground_um` µm: every
    /// `None` field filled in.
    pub fn fit(&self, ground_um: f32) -> Cracks {
        let ground = self.ground_um.unwrap_or(ground_um);
        let island = self.island_mm.unwrap_or_else(|| island_for(ground));
        Cracks { ground_um: Some(ground), island_mm: Some(island), width_um: Some(self.width_um.unwrap_or(STRAIN * island * 1000.0)), ..*self }
    }
    /// Ground thickness, µm (0 if not given yet).
    pub fn ground(&self) -> f32 {
        self.ground_um.unwrap_or(0.0)
    }
    /// Median island size, mm.
    pub fn island(&self) -> f32 {
        self.island_mm.unwrap_or_else(|| island_for(self.ground()))
    }
    /// Opening of a primary crack, µm.
